Matching Ayahs
- = আলিফ, লাম, মীম। 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = সিহঁতেই তেওঁলোকৰ প্ৰভুৰ পৰা সৎপথ প্ৰাপ্ত, আৰু সিহঁতেই সফলকাম। 2:5; 31:5
- = হে ইস্ৰায়েলৰ সন্তানসকল! মোৰ সেই অনুগ্ৰহৰ কথা স্মৰণ কৰা যি মই তোমালোকক প্ৰদান কৰিছিলো আৰু মই তোমালোকক জগতসমূহৰ ওপৰত শ্ৰেষ্ঠতা দিছিলো। 2:47; 2:122
- = সেইটো এটা সম্প্ৰদায় যি অতীতত গৈছে। তেওঁলোকে যি কৰিছে তাৰ ফল তেওঁলোকৰ বাবে, আৰু তোমালোকে যি কৰিছা তাৰ ফল তোমালোকৰ বাবে। আৰু তেওঁলোকে যি কৰিছিল সেই সম্বন্ধে তোমালোকক সোধা নহ'ব। 2:134; 2:141
- = তাতে সিহঁত চিৰকাল থাকিব। শাস্তি সিহঁতৰ পৰা লঘু কৰা নহ'ব আৰু সিহঁতক অৱকাশো দিয়া নহ'ব। 2:162; 3:88
- = কিন্তু যিসকলে সেই পাছত তওবা কৰে আৰু নিজকে সংশোধন কৰে, তেন্তে নিশ্চয় আল্লাহ ক্ষমাশীল, পৰম দয়ালু। 3:89; 24:5
- = আৰু যিসকলে কুফুৰী কৰে আৰু আমাৰ আয়াতসমূহক অস্বীকাৰ কৰে, সিহঁতেই জাহান্নামৰ অধিবাসী। 5:10; 5:86
- = আৰু তেওঁলোকৰ প্ৰভুৰ নিদৰ্শনসমূহৰ পৰা তেওঁলোকৰ ওচৰলৈ কোনো নিদৰ্শন নাহে, কিন্তু তেওঁলোকে তাৰ পৰা মুখ ঘূৰাই লয়। 6:4; 36:46
- = আৰু আপোনাৰ আগতেও ৰাছুলসকলক উপহাস কৰা হৈছিল; কিন্তু যিসকলে উপহাস কৰিছিল, তেওঁলোকক সেয়ে ঘেৰি ধৰিলে যি বিষয়ে তেওঁলোকে উপহাস কৰিছিল। 6:10; 21:41
- = কোৱা, "মই যদি মোৰ প্ৰভুৰ অৱাধ্যতা কৰো, তেন্তে মহাদিনৰ শাস্তিৰ ভয় কৰো।" 6:15; 39:13
- = গতিকে ভূকম্পনে তেওঁলোকক ধৰি পেলালে, তেতিয়া তেওঁলোক নিজ ঘৰত আছোঁতেই লুটি পৰি থাকিল। 7:78; 7:91
- = তেতিয়া তেওঁ নিজৰ লাঠি দলিয়াই দিলে, আৰু সেয়া তৎক্ষণাত এটা স্পষ্ট সাপ হৈ পৰিল। 7:107; 26:32
- = আৰু তেওঁ নিজৰ হাত ওলিয়াই দিলে, তেতিয়া সেয়া দৰ্শকসকলৰ বাবে উজ্জ্বল শ্বেত বৰণীয়া হৈ পৰিল। 7:108; 26:33
- = তেওঁলোকে ক'লে, "আমি বিশ্বজগতৰ প্ৰভুত ঈমান আনিলো।" 7:121; 26:47
- = মুছা আৰু হাৰুনৰ প্ৰভু। 7:122; 26:48
- = আৰু মই তেওঁলোকক সময় দিম; নিশ্চয় মোৰ পৰিকল্পনা সুদৃঢ়। 7:183; 68:45
- = তেৱেঁই নিজ ৰাছুলক সৎপথ আৰু সত্য ধৰ্মৰ সৈতে প্ৰেৰণ কৰিছে, যাতে তেওঁ সকলো ধৰ্মৰ ওপৰত ইয়াক প্ৰভাৱশালী কৰে, যদিও মুশৰিকসকলে অস্বীকাৰ কৰে। 9:33; 61:9
- = হে নবী! কাফিৰ আৰু মুনাফিকসকলৰ বিৰুদ্ধে যুদ্ধ কৰা আৰু তেওঁলোকৰ প্ৰতি কঠোৰ হোৱা; আৰু তেওঁলোকৰ আশ্ৰয়স্থল জাহান্নাম, আৰু সি কিমান নিকৃষ্ট প্ৰত্যাৱৰ্তনস্থল! 9:73; 66:9
- = আৰু তেওঁলোকে কয়, "এই প্ৰতিশ্ৰুতি কেতিয়া, যদি তোমালোক সত্যবাদী?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = আৰু নিশ্চয় আমি মুছাক আমাৰ নিদৰ্শন আৰু স্পষ্ট কৰ্তৃত্বৰ সৈতে প্ৰেৰণ কৰিছিলো। 11:96; 40:23
- = আৰু নিশ্চয় আমি মুছাক কিতাব দিছিলো, কিন্তু তাত মতভেদ সৃষ্টি হ'ল। আৰু যদি আপোনাৰ প্ৰভুৰ পৰা এটা পূৰ্বৱৰ্তী কথাই নাথাকিলহেঁতেন, তেন্তে তেওঁলোকৰ মাজত চূড়ান্ত সিদ্ধান্ত লোৱা হ'লহেঁতেন। আৰু নিশ্চয় তেওঁলোক ইয়াৰ বিষয়ে সন্দিহান। 11:110; 41:45
- = আল্লাহৰ বাবে সেইটো কঠিন নহয়। 14:20; 35:17
- = "যেতিয়া মই তাক সুস্থিৰ কৰিম আৰু মোৰ সৃষ্ট আত্মাৰ পৰা তাত ফুক দিম, তেতিয়া তোমালোক তেওঁৰ বাবে সিজদা কৰি পৰা।" 15:29; 38:72
- = তেতিয়া ফিৰিস্তাসকলে সিজদা কৰিলে—সকলোৱে একেলগে। 15:30; 38:73
- = (আল্লাহে) ক'লে, "তেন্তে তাত পৰা ওলাই যোৱা, কিয়নো নিশ্চয় তুমি বিতাড়িত।" 15:34; 38:77
- = তেওঁ ক'লে, "হে মোৰ প্ৰভু! তেন্তে মোক পুনৰুত্থানৰ দিনলৈকে কিছু সময় দিয়া।" 15:36; 38:79
