- তেওঁলোকে পৃথিৱীত বিচৰণ কৰে আৰু চাইছে যে তেওঁলোকৰ আগৰ লোকসকলৰ পৰিণতি কেনেকুৱা হৈছিল। (يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن قَبْلِهِمْ) 12:109; 30:9; 30:42; 35:44; 40:82; 47:10
- আৰু জনাই অত্যাচাৰী, যিজনে আল্লাহৰ ওপৰত মিছা কথা ৰচনা কৰে বা অস্বীকাৰ কৰে? (وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَى عَلَى اللَّهِ كَذِبًا أَوْ كَذَّبَ) 6:21; 7:37; 10:17; 29:68
- নিশ্চয় তোমাৰ প্ৰভু তেওঁ ভালদৰে জানে কোন তেওঁৰ পথৰ পৰা বিচলিত হয়, আৰু তেওঁ ভালদৰে জানে। (إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 6:117; 16:125; 53:30; 68:7
- তেওঁলোকে পৃথিৱীত বিচৰণ কৰা নাইনে আৰু চোৱা নাইনে যে তেওঁলোকৰ আগৰ লোকসকলৰ পৰিণতি কেনেকুৱা হৈছিল? (أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن) 30:9; 35:44; 40:82; 47:10
- তেওঁলোকৰ বাবে তেওঁলোকৰ প্ৰভুৰ ওচৰত তেওঁলোকৰ পুৰস্কাৰ আছে, তেওঁলোকৰ কোনো ভয় নাই আৰু তেওঁলোকে দুখ নকৰে। (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:62; 2:262; 2:274; 2:277
- আৰু যিসকলে ঈমান আনিছিল আৰু সৎকৰ্ম কৰিছিল তেওঁলোকক সেই জান্নাতসমূহত প্ৰৱেশ কৰোৱা হ'ল যাৰ তলত নৈবোৰ বৈ আছে। (وَأُدْخِلَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 14:23; 22:14; 22:23; 47:12
- তেওঁ ক'লে: "হে মোৰ সম্প্ৰদায়! আল্লাহৰ ইবাদত কৰা, তেওঁৰ বাহিৰে তোমালোকৰ কোনো ইলাহ নাই, তোমালোকে ভয় নকৰা নেকি?" (قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا) 7:65; 11:84; 23:23
- তেওঁলোকৰ ধন-সম্পত্তি আৰু তেওঁলোকৰ সন্তান-সন্ততিয়ে আল্লাহৰ ওচৰত তেওঁলোকৰ কোনো কাম নাহিব, আৰু তেওঁলোকেই। (لَن تُغْنِيَ عَنْهُمْ أَمْوَالُهُمْ وَلَا أَوْلَادُهُم مِّنَ اللَّهِ شَيْئًا وَأُولَئِكَ) 3:10; 3:116; 58:17
- জান্নাতসমূহ যাৰ তলত নৈবোৰ বৈ আছে, তাত তেওঁলোকে চিৰস্থায়ী হ'ব, আৰু সেইটোৱেই হ'ল মহান সফলতা। (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ الْفَوْزُ الْعَظِيمُ) 4:13; 9:89
- তেওঁলোকৰ আগৰ লোকসকলৰ বাতৰি তেওঁলোকৰ ওচৰলৈ অহা নাইনে? নূহ, আদ আৰু সামূদৰ সম্প্ৰদায়ৰ? (أَلَمْ يَأْتِهِمْ نَبَأُ الَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ) 9:70; 14:9
- আল্লাহৰ ফালে মোৰ সহায়কাৰীসকল কোন? শিষ্যসকলে ক'লে: "আমিয়েই আল্লাহৰ সহায়কাৰী, আমি ঈমান আনিলো।" (مَنْ أَنصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ آمَنَّا) 3:52; 61:14
- তোমাৰ প্ৰভু তেওঁ ভালদৰে জানে কোন তেওঁৰ পথৰ পৰা বিচলিত হৈছে, আৰু তেওঁ ভালদৰে জানে সৎপথপ্ৰাপ্তসকলক। (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ) 16:125; 68:7
- এইটো এই কাৰণে যে আল্লাহ তেওঁই সত্য, আৰু তেওঁলোকে তেওঁৰ বাহিৰে যাক মাতি আছে সেয়া অসাৰ। (ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ) 22:62; 31:30
- আৰু যিয়ে আল্লাহ আৰু তেওঁৰ ৰাছুলৰ আজ্ঞা পালন কৰে, আল্লাহে তেওঁক জান্নাতসমূহত প্ৰৱেশ কৰাব যাৰ তলত নৈবোৰ বৈ আছে। (وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 4:13; 48:17
- নিশ্চয় আল্লাহে তোমালোকৰ বাবে নিষিদ্ধ কৰিছে মৃত জন্তু, তেজ, গাহৰিৰ মাংস আৰু যি আল্লাহৰ বাহিৰে আনৰ নামত উছৰ্গা কৰা হয়। (إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 16:115
- যে তোমালোকে আল্লাহৰ বাহিৰে আনৰ ইবাদত নকৰিবা, নিশ্চয় মই তোমালোকৰ বাবে মহা দিনৰ শাস্তিৰ ভয় কৰো। (أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ) 11:26; 46:21
- এইটো গায়েবী বাতৰিৰ ভিতৰত যা আমি তোমালৈ ওহী কৰিছো, আৰু তেওঁলোকে সিদ্ধান্ত লওঁতে তুমি তেওঁলোকৰ ওচৰত নাছিলা। (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- তোমালোকে আচৰিত হৈছা নে যে তোমালোকৰ প্ৰভুৰ পৰা তোমালোকৰ মাজৰ এজন মানুহৰ ওপৰত স্মাৰক অহা, যাতে তেওঁ তোমালোকক সতৰ্ক কৰায়? (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- কোৱা: "নিশ্চয় মোক নিষেধ কৰা হৈছে যে মই আল্লাহৰ বাহিৰে যিসকলক তোমালোকে মাতা তেওঁলোকৰ ইবাদত কৰো।" (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- তেওঁলোকৰ পত্নী বা তেওঁলোকৰ ডান হাতে মালিকানা কৰা দাসীসকলৰ বাহিৰে, তেতিয়া তেওঁলোক নিন্দিত নহয়। (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- এই কাৰণে যে আল্লাহে ৰাতিক দিনত প্ৰৱেশ কৰায় আৰু দিনক ৰাতিত প্ৰৱেশ কৰায়। (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- জুই, তেতিয়া তেওঁ নিজ পৰিয়ালক ক'লে: "তোমালোকে ৰোৱা, নিশ্চয় মই জুই দেখা পালো, হয়তো মই তাৰ পৰা তোমালোকলৈ কিবা আনিব পাৰো।" (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- তেওঁ ক'লে: "মই তাতকৈ শ্ৰেষ্ঠ, তুমি মোক জুইৰ পৰা সৃষ্টি কৰিলা আৰু তেওঁক মাটিৰ পৰা সৃষ্টি কৰিলা।" (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- আৰু যেতিয়া তেওঁলোকক কোৱা হয়: "আল্লাহই যি অৱতীৰ্ণ কৰিছে তাৰ ফালে আৰু ৰাছুলৰ ফালে আহা।" (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- আৰু তেওঁলোকৰ বাবে দুখ নকৰিবা আৰু তেওঁলোকৰ ষড়যন্ত্ৰৰ বাবে সংকীৰ্ণ নহ'বা। (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- আৰু যদি আল্লাহে তোমাক কোনো ক্ষতি স্পৰ্শ কৰায়, তেন্তে তেওঁৰ বাহিৰে আন কোনো আতৰোৱাকাৰী নাই, আৰু যদি। (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- তেওঁলোকৰ আগৰ পুৰুষসকল, তেওঁলোকে তেওঁলোকৰ বাসগৃহসমূহত বিচৰণ কৰে, নিশ্চয় এইবোৰত নিদৰ্শন আছে। (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- আৰু আমি তেওঁলোকৰ অন্তৰত আৱৰণ দিলো যে তেওঁলোকে ইয়াক বুজি নাপায়, আৰু তেওঁলোকৰ কাণত বধিৰতা, আৰু যদিও। (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- তেওঁলোকৰ ৰাছুলসকলে প্ৰমাণসহ আহিল, কিন্তু আল্লাহ তেওঁলোকৰ ওপৰত অত্যাচাৰ কৰা নাছিল, কিন্তু তেওঁলোকে নিজেই নিজৰ ওপৰত অত্যাচাৰ কৰিছিল। (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- আৰু পৃথিৱী, আৰু আল্লাহৰ বাহিৰে তোমালোকৰ কোনো ৰক্ষক আৰু সহায়কাৰী নাই। (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- তাৰ পিছত তোমালোকক গায়েব আৰু শাহাদতৰ জ্ঞানীৰ ফালে ঘূৰাই অনা হ'ব, আৰু তেওঁ তোমালোকক তোমালোকে কি কৰিছিলা তাৰ বাতৰি দিব। (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- ৰাতি যে তোমালোকে তাত বিশ্ৰাম লোৱা আৰু দিনা যে তোমালোকে দেখা পোৱা, নিশ্চয় এইবোৰত চিন্তাশীল সম্প্ৰদায়ৰ বাবে নিদৰ্শন আছে। (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- আৰু তোমাৰ প্ৰভুৰ পৰা তোমালৈ যি অৱতীৰ্ণ হৈছে তাৰ বাবে তেওঁলোকৰ বহুতো লোকৰ বিদ্ৰোহ আৰু কুফুৰি বৃদ্ধি পাব। (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
