- তোমালোকক গায়েব আৰু শাহাদতৰ জ্ঞানীৰ ফালে ঘূৰাই অনা হ'ব, আৰু তেওঁ তোমালোকক তোমালোকে কি কৰিছিলা তাৰ বাতৰি দিব। (تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 9:105; 62:8
- তোমালোকৰ পুত্ৰসকলক হত্যা কৰে আৰু তোমালোকৰ নাৰীসকলক জীৱিত ৰাখে, আৰু এইবোৰত তোমালোকৰ প্ৰভুৰ পৰা মহান পৰীক্ষা আছে। (أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ) 2:49; 7:141; 14:6
- নিশ্চয় তোমাৰ প্ৰভু তেওঁ ভালদৰে জানে কোন তেওঁৰ পথৰ পৰা বিচলিত হয়, আৰু তেওঁ। (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 16:125; 53:30; 68:7
- আল্লাহ যিজনৰ বাবে আকাশমণ্ডলত যি আছে আৰু পৃথিৱীত যি আছে। (اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 14:2; 34:1; 42:53
- তোমালোকৰ আগৰ সম্প্ৰদায়সমূহৰ মাজত, জিন আৰু মানুহৰ। (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- আল্লাহৰ ইবাদত কৰা, তেওঁৰ বাহিৰে তোমালোকৰ কোনো ইলাহ নাই, তোমালোকে ভয় নকৰা নেকি? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
- আৰু আমি তেওঁলোকৰ অন্তৰত আৱৰণ দিলো যে তেওঁলোকে ইয়াক বুজি নাপায়, আৰু তেওঁলোকৰ কাণত বধিৰতা। (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- তেওঁ তেওঁলোকৰ মাজত কিয়ামতৰ দিনা সেই বিষয়ে বিচাৰ কৰিব যি বিষয়ে তেওঁলোকে বিবাদ কৰিছিল। (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- তেওঁ ক'লে: "হে মোৰ সম্প্ৰদায়! তোমালোকে চোৱা, যদি মই মোৰ প্ৰভুৰ পৰা স্পষ্ট প্ৰমাণত থাকো।" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- এইটো তোমালোকৰ হাতে আগবঢ়োৱা বস্তুৰ বাবে, আৰু আল্লাহ বান্দাসকলৰ প্ৰতি অত্যাচাৰী নহয়। (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- তেওঁলোকৰ বাবে পৃথিৱীত অপমান আৰু আখিৰাতত মহান শাস্তি আছে। (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- আকাশমণ্ডলত যি আছে আৰু পৃথিৱীত যি আছে, আৰু আল্লাহ অভিভাৱক হিচাপে যথেষ্ট। (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- কিন্তু যিসকলে ঈমান আনিছে আৰু সৎকৰ্ম কৰিছে, তেওঁলোকৰ বাবে অসীম পুৰস্কাৰ আছে। (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- যে তুমি মোৰ সৈতে সেই বস্তু অংশীদাৰ কৰা যাৰ বিষয়ে তোমাৰ কোনো জ্ঞান নাই, সেয়ে তেওঁলোকৰ আজ্ঞা নাপালন কৰিবা। (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- নিশ্চয় এইটো এক স্মাৰক, গতিকে যিয়ে ইচ্ছা কৰে তেওঁ নিজ প্ৰভুলৈ পথ গ্ৰহণ কৰক। (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- আৰু যিয়ে কৃতজ্ঞ হয়, তেওঁ কৃতজ্ঞ হয় নিজৰ বাবে, আৰু যিয়ে অস্বীকাৰ কৰে, তেন্তে। (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- যিসকলে নামাজ কায়েম কৰে আৰু যাকাত দিয়ে আৰু তেওঁলোকে আখিৰাতৰ প্ৰতি দৃঢ় বিশ্বাস পোষণ কৰে। (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- ইব্ৰাহীম, ইসমাইল, ইছহাক, ইয়াকুব, আৰু বংশধৰসকল, আৰু মূছা আৰু ঈছাক যি দিয়া হৈছিল। (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- দলবদ্ধভাবে, যেতিয়ালৈকে তেওঁলোকে তাত উপস্থিত হয়, তেতিয়া তাৰ দুৱাৰবোৰ খোলা হয় আৰু তাৰ ৰক্ষকসকলে তেওঁলোকক কয়। (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- আল্লাহে তোমালোকক তোমালোকৰ শপথৰ অসাৰ কথাবোৰৰ বাবে পাক নকৰে, কিন্তু তোমালোকক পাক কৰে তাৰ বাবে। (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- দয়া, তেওঁলোকে তাৰ বাবে উৎফুল্ল হয়, আৰু যদি তেওঁলোকে নিজ হাতে আগবঢ়োৱা কাৰণে কোনো অনিষ্ট স্পৰ্শ কৰে। (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- যাৰ তলত নৈবোৰ বৈ আছে, তাত তেওঁলোকে চিৰস্থায়ী হ'ব, আৰু কাম কৰাসকলৰ পুৰস্কাৰ কিমান উত্তম! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- আল্লাহে জানেন আকাশমণ্ডলত যি আছে আৰু পৃথিৱীত যি আছে, আৰু আল্লাহ। (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- আল্লাহৰ আজ্ঞা পালন কৰা আৰু ৰাছুলৰ আজ্ঞা পালন কৰা, যদি তোমালোকে মুখ ঘুৰাই দিয়া তেন্তে তেওঁৰ ওপৰত। (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- তেওঁলোকৰ বাবে তেওঁলোকৰ প্ৰভুৰ ওচৰত তেওঁলোকৰ পুৰস্কাৰ আছে, তেওঁলোকৰ কোনো ভয় নাই আৰু তেওঁলোকে। (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- আৰু তেওঁলোকে ক'লে: "আমি অস্থি আৰু চূৰ্ণ-বিচূৰ্ণ হৈ গ'লেও আমি নতুন সৃষ্টি হিচাপে পুনৰুত্থিত হ'ম?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- আৰু তেওঁলোকে আল্লাহৰ বাহিৰে নিজৰ বাবে কোনো ৰক্ষক আৰু সহায়কাৰী নাপায়। (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- "কিমান কাল তুমি থাকিলা?" তেওঁ ক'লে: "মই এদিন বা এদিনৰ কিছু অংশ থাকিলো।" তেওঁ ক'লে। (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- কিয়ামতৰ দিনলৈকে চিৰস্থায়ী, আল্লাহৰ বাহিৰে কোন ইলাহ আছে যিয়ে তোমালোকলৈ আহিব? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- যিয়ে সৎকৰ্ম কৰে, পুৰুষ বা নাৰী, আৰু তেওঁ মুমিন হয়। (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- যিসকলে আল্লাহৰ পথৰ পৰা বাধা দিয়ে আৰু তাক বেঁকা কৰিব বিচাৰে, আৰু তেওঁলোকে আখিৰাতৰ প্ৰতি। (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- তোমালোকে য'ত ইচ্ছা কৰা, কিন্তু এই গছৰ ওচৰলৈ নাযাবা, তেন্তে তোমালোকে অত্যাচাৰী হ'বা। (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- কোৱা: "হে মোৰ সম্প্ৰদায়! তোমালোকে নিজ স্থানত কাম কৰা, মইও কাম কৰিছো, সোনকালে তোমালোকে জানিবা।" (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- নিশ্চয় ক্ষতিগ্ৰস্তসকলেই যিসকলে কিয়ামতৰ দিনা নিজকে আৰু নিজ পৰিয়ালক ক্ষতি কৰিলে, সাৱধান। (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- যিয়ে নিজৰ বাবে হেদায়েত পায়, আৰু যিয়ে পথভ্ৰষ্ট হয়, তেওঁ পথভ্ৰষ্ট হয় নিজৰ বাবে, আৰু। (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- আৰু যিসকলে কুফুৰি কৰে তেওঁলোকে কয়: "তেওঁৰ ওপৰত তেওঁৰ প্ৰভুৰ পৰা কোনো নিদৰ্শন কিয় অৱতীৰ্ণ কৰা নহ'ল?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- যিজনে তোমালোকৰ বাবে ৰাতি সৃষ্টি কৰিলে যাতে তোমালোকে তাত বিশ্ৰাম লোৱা আৰু দিনা দ্ৰষ্টা হিচাপে, নিশ্চয়। (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- এনে দিন অহাৰ আগতে যাৰ কোনো কিনা-বেচা নাই আৰু কোনো। (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- তেওঁলোকে চিন্তা কৰে যে তেওঁলোকৰ সাথীৰ কোনো উন্মাদনা নাই, তেওঁ সতৰ্ককাৰীৰ বাহিৰে আন নহয়। (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- তাত তেওঁলোকে চিৰস্থায়ী হ'ব, তেওঁলোকৰ পৰা শাস্তি লাঘৱ কৰা নহ'ব আৰু তেওঁলোকক অৱকাশ দিয়া নহ'ব। (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- তুমি তোমাৰ চকু নিদিবা যি বস্তু আমি তেওঁলোকৰ কিছুমান দম্পতীক উপভোগ কৰিবলৈ দিছো। (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- আৰু মানুহক তেওঁলোকৰ বস্তু নুন্যূন নকৰিবা আৰু পৃথিৱীত অনিষ্ট বিস্তাৰ নকৰিবা। (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- আৰু তেওঁৰ ওপৰত শান্তি থাকক যিদিনা তেওঁ জন্ম ল'লে, যিদিনা তেওঁ মৃত্যুবৰণ কৰে আৰু যিদিনা তেওঁ জীৱিত অৱস্থাত পুনৰুত্থিত হয়। (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- হে মোৰ সম্প্ৰদায়! তোমালোকে নিজ স্থানত কাম কৰা, মইও কাম কৰিছো, সোনকালে তোমালোকে জানিবা কোন। (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- আৰু কোনো ৰাছুলৰ বাবে সম্ভৱ নহয় যে তেওঁ আল্লাহৰ অনুমতি অবিহনে কোনো নিদৰ্শন লৈ আহে। (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- তাৰ পিছত প্ৰত্যেক ব্যক্তিক তাই উপাৰ্জন কৰা বস্তু সম্পূৰ্ণৰূপে প্ৰদান কৰা হ'ব, আৰু তেওঁলোকৰ ওপৰত অত্যাচাৰ কৰা নহ'ব। (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- পুৰুষ বা নাৰী, আৰু তেওঁ মুমিন হয়, তেন্তে তেওঁলোক জান্নাতত প্ৰৱেশ কৰিব। (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- তেওঁ কোনো সন্তান গ্ৰহণ কৰা নাই আৰু ৰাজত্বত তেওঁৰ কোনো অংশীদাৰ নাই। (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- আৰু আল্লাহে যাক হেদায়েত দিয়ে তেৱেঁই হেদায়েতপ্ৰাপ্ত, আৰু যাক পথভ্ৰষ্ট কৰে তুমি কেতিয়াও নাপাবা। (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- চোৱা তেওঁলোকে তোমাৰ বাবে কেনে উপমা দিলে, গতিকে তেওঁলোকে পথভ্ৰষ্ট হ'ল, গতিকে তেওঁলোকে কোনো পথ পাব নোৱাৰিলে। (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- কোৱা: "মই মোৰ প্ৰভুৰ অবাধ্য হ'লে মহা দিনৰ শাস্তিৰ ভয় কৰো।" (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- তেওঁলোকৰ লাজৰ ঠাই দুয়োখন উলঙ্গ হ'ল আৰু তেওঁলোকে জান্নাতৰ পাতৰে নিজকে আবৃত কৰিবলৈ ধৰিলে। (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- আৰু আল্লাহৰ বাহিৰে যাক ইচ্ছা কৰা মাতা, যদি তোমালোকে সত্যবাদী হোৱা। (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- পৃথিৱীৰ সকলো বস্তু আৰু তাৰ সমপৰিমাণ, যাতে তেওঁলোকে তাৰ দ্বাৰা মুক্তি পায়। (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- আমি তোমালোকক যি দিছো সেয়া শক্তিশালীভাৱে গ্ৰহণ কৰা আৰু তাত যি আছে তাৰ সোঁৱৰণ কৰা, যাতে তোমালোকে তাকৱা অৱলম্বন কৰা। (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- তোমালোকে সি অশ্লীল কাম কৰা নে যি তোমালোকৰ আগতে বিশ্ববাসীৰ কোনেও কৰা নাই? (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- আৰু আল্লাহৰ বাবে আকাশমণ্ডলত যি আছে আৰু পৃথিৱীত যি আছে, আৰু আল্লাহ আছিল। (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- তেওঁলোকে কৰা পাপসমূহে তেওঁলোকক ঘেৰি ধৰিলে আৰু তেওঁলোকে যি উপহাস কৰিছিল সেয়া তেওঁলোকৰ ওপৰত পৰিল। (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
- তোমালোকৰ মাজৰ পৰা এজন ৰাছুল, যিয়ে তোমালোকক আমাৰ আয়াতসমূহ পঢ়ি শুনায় আৰু তোমালোকক পৱিত্ৰ কৰে আৰু কিতাব আৰু হিকমত শিক্ষা দিয়ে। (رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ) 2:151; 62:2
- তাৰ পৰা বাৰটা ঝৰণা উৎপন্ন হ'ল, প্ৰত্যেক সম্প্ৰদায়ে নিজ পানী পান কৰাৰ স্থান জানিছিল। (مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ) 2:60; 7:160
- কেৱল ধাৰণা, নিশ্চয় ধাৰণাই সত্যৰ পৰা কোনো উপকাৰ নিদিয়ে। (إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا) 10:36; 53:28
- যেতিয়া মই তাক সুষম কৰিম আৰু তাত মোৰ আত্মাৰ পৰা ফুঁ দিম, তেতিয়া তোমালোকে তাক সিজদা কৰি পৰা। (فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ) 15:29; 38:72
- গৃহৰ পৰিণতি কাৰ বাবে, নিশ্চয় অত্যাচাৰীসকল সফল নহয়। (مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ) 6:135; 28:37
- যিজনে আকাশমণ্ডল আৰু পৃথিৱী সৃষ্টি কৰিছে, তেওঁ তেওঁলোকৰ দৰে সৃষ্টি কৰিবলৈ সক্ষম। (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ قَادِرٌ عَلَى أَن يَخْلُقَ مِثْلَهُمْ) 17:99; 36:81
- মুমিন পুৰুষ আৰু মুমিন নাৰীসকলৰ বাবে জান্নাতসমূহ যাৰ তলত নৈবোৰ বৈ আছে, তাত তেওঁলোকে চিৰস্থায়ী হ'ব। (الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 9:72; 48:5
- আৰু যদি তুমি তেওঁলোকক সোধা কোনে আকাশমণ্ডল আৰু পৃথিৱী সৃষ্টি কৰিছে, তেওঁলোকে নিশ্চয় ক'ব "আল্লাহ", কোৱা। (وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ قُلِ) 31:25; 39:38
- আৰু নিশ্চয় আমি এই কুৰআনত মানুহৰ বাবে প্ৰত্যেক দৃষ্টান্ত বৰ্ণনা কৰিছো। (وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِي هَذَا الْقُرْآنِ مِن كُلِّ مَثَلٍ) 30:58; 39:27
- আমাৰ ৰাছুলসকল লূতৰ ওচৰলৈ আহিল, তেওঁ তেওঁলোকৰ বাবে দুশ্চিন্তাগ্ৰস্ত হ'ল আৰু তেওঁলোকৰ কাৰণে সংকীৰ্ণ হ'ল, আৰু ক'লে। (جَاءَتْ رُسُلُنَا لُوطًا سِيءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ) 11:77; 29:33
- আৰু যেতিয়া আমি ফিৰিস্তাসকলক ক'লো: "আদমক সিজদা কৰা", তেতিয়া তেওঁলোকে সিজদা কৰিলে, ইবলীসৰ বাহিৰে, যিয়ে অস্বীকাৰ কৰিলে। (وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ أَبَى) 2:34; 20:116
