- আৰু মাদয়ানলৈ তেওঁলোকৰ ভাতৃ চুআইবক (পঠিয়ালো), তেওঁ ক'লে: হে মোৰ সম্প্ৰদায়ৰ লোকসকল, আল্লাহৰ ইবাদত কৰা। (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- এইটো গায়েবী বাতৰিৰ অংশ, আমি তোমাক অহী কৰি দিওঁ, আৰু তুমি। (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- যেতিয়া তেওঁলোকৰ নিৰ্ধাৰিত সময় আহে, তেতিয়া তেওঁলোকে এক মুহূৰ্তও পলম নকৰে, আৰু আগবাঢ়িও নাযায়। (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- আৰু তোমালোকে চয়তানৰ পদচিহ্ন অনুসৰণ নকৰিবা, নিশ্চয় সি তোমালোকৰ প্ৰকাশ্য শত্ৰু। (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- মানুহৰ মাজত এনে লোকো আছে যিয়ে কোনো জ্ঞান নোহোৱাকৈ আল্লাহৰ বিষয়ে বিতণ্ডা কৰে। (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- আল্লাহে যাক ইচ্ছা কৰে তাক দিয়ে, আৰু আল্লাহ মহান অনুগ্ৰহশীল। (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- প্ৰত্যেক প্ৰাণীক তেওঁৰ কৃতকৰ্মৰ পূৰ্ণ প্ৰতিদান দিয়া হ'ব, আৰু তেওঁলোকৰ ওপৰত কোনো অন্যায় কৰা নহ'ব। (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- আৰু তোমালোকে আল্লাহে নিষিদ্ধ কৰা প্ৰাণক ন্যায়যুক্ত কাৰণৰ বাহিৰে হত্যা নকৰিবা। (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- যেতিয়া তেওঁ কোনো কাম কৰিবলৈ সিদ্ধান্ত লয়, তেতিয়া তেওঁ কেৱল কয়: হওক। (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- তোমালোকে জাহান্নামৰ দুৱাৰসমূহত প্ৰৱেশ কৰা, তাত চিৰস্থায়ী হৈ থাকা; অহংকাৰীসকলৰ বাসস্থান কিমান নিকৃষ্ট! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- তুমি সিহঁতক দেখা নাইনে যিসকলক কিতাবৰ পৰা অংশ দিয়া হৈছিল? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- তেওঁলোকৰ বাবে জান্নাত আছে যাৰ তলত নৈবাহিনী প্ৰবাহিত, তাত তেওঁলোক চিৰস্থায়ী হৈ থাকিব। (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- হে মোৰ সম্প্ৰদায়ৰ লোকসকল, তোমালোকে নিজৰ স্থানত কাম কৰি থাকা, মইও কাম কৰিছো, অচিৰেই তোমালোকে জানিবা। (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- যি আল্লাহ আৰু তেওঁৰ ৰাছুলৰ বিৰোধিতা কৰে, তেওঁৰ বাবে জাহান্নামৰ জুই আছে, তাত তেওঁ চিৰস্থায়ী হৈ থাকিব। (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- আমি তেওঁলোকৰ অন্তৰত আৱৰণি দিছো যাতে তেওঁলোকে (কোৰআন) নুবুজে, আৰু তেওঁলোকৰ কাণত বধিৰতা। (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- কোনো জনপদত সতৰ্ককৰ্তা প্ৰেৰণ নকৰাকৈ, তাত থকা সম্পদশালীসকলে কয়: নিশ্চয় আমি। (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- তেওঁলোকে ক'লে: তোমাৰ প্ৰতিপালকক আমাৰ বাবে প্ৰাৰ্থনা কৰা, যাতে তেওঁ আমাক স্পষ্ট কৰি দিয়ে যে সি কি। (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- তেওঁলোকে নিশ্চয় ক'ব: আল্লাহ। কোৱা: সকলো প্ৰশংসা আল্লাহৰ, কিন্তু তেওঁলোকৰ অধিকাংশই। (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- তেওঁৰ সম্প্ৰদায়ৰ উত্তৰ কেৱল এইটোৱেই আছিল যে তেওঁলোকে ক'লে: তোমালোকে সিহঁতক উলিয়াই দিয়া। (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- যাৰ তলত নৈবাহিনী প্ৰবাহিত, তাত তেওঁলোক চিৰস্থায়ী হৈ থাকিব; এইটোৱেই হৈছে মহান সফলতা। (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- তেওঁলোকেই তেওঁলোকৰ প্ৰতিপালকৰ পৰা পথনিৰ্দেশনত থাকে, আৰু তেওঁলোকেই সফলকামী। (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- তাক এনে শাস্তিয়ে আহিব যিয়ে তাক অপমানিত কৰিব, আৰু তাৰ ওপৰত স্থায়ী শাস্তি নামিব। (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- পৃথিৱীত ফুৰা-চাকৰা কৰা আৰু অস্বীকাৰকাৰীসকলৰ পৰিণতি কেনেকুৱা হৈছিল চোৱা। (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- তেওঁলোকে কেতিয়াও তাৰ কামনা নকৰিব, তেওঁলোকৰ হাতে আগবঢ়োৱা কাৰ্যৰ বাবে, আৰু আল্লাহ গৰিষ্ঠান্যায়কাৰীসকলক জানে। (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- তেওঁয়ে ভালকৈ জানে কোনে তেওঁৰ পথৰ পৰা পথভ্ৰষ্ট হৈছে, আৰু তেওঁয়ে ভালকৈ জানে। (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- নিশ্চয় আল্লাহ মোৰ প্ৰতিপালক আৰু তোমালোকৰো প্ৰতিপালক, গতিকে তেওঁৰেই ইবাদত কৰা; এইটোৱেই সৰল পথ। (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- তেওঁ মানুহৰ প্ৰতি অনুগ্ৰহশীল, কিন্তু তেওঁলোকৰ অধিকাংশই কৃতজ্ঞতা প্ৰকাশ নকৰে। (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- আকাশমণ্ডল আৰু পৃথিৱী আৰু সেই দুয়োৰ মাজত যি আছে, সেইবোৰ সত্য আৰু নিৰ্দিষ্ট সময়ৰ বাবেহে (সৃষ্টি কৰা হৈছে)। (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- তেওঁলোকক ছেড়া দিয়া, যাতে তেওঁলোকে নিজৰ অসাৰ কথাত মত্ত হৈ খেলি-ধেমালি কৰি থাকে, যেতিয়ালৈকে তেওঁলোকে সেই দিনৰ সন্মুখীন হয়, যাৰ প্ৰতিশ্ৰুতি তেওঁলোকক দিয়া হৈছে। (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- যেতিয়া তেওঁলোকে মুমিনসকলক লগ পায়, তেতিয়া কয়: আমি ঈমান পাইছো, আৰু যেতিয়া একান্ত হৈ পৰে। (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- তেওঁলোকে তাওৰাত আৰু ইঞ্জীল আৰু তেওঁলোকৰ প্ৰতিপালকৰ পৰা অৱতীৰ্ণ কৰা বিষয়বস্তু কায়েম কৰে। (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- তেওঁ জানে তেওঁলোকৰ সম্মুখত কি আছে আৰু তেওঁলোকৰ পশ্চাতে কি আছে, আৰু তেওঁলোকে তাক (জ্ঞানৰে) পৰিবেষ্টিত কৰিব নোৱাৰে। (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- আৰু তেওঁয়েই সেইজন যিয়ে আকাশমণ্ডল আৰু পৃথিৱী ছয় দিনত সৃষ্টি কৰিছে। (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- নিশ্চয় ইয়াত তোমালোকৰ বাবে এটা নিদৰ্শন আছে, যদি তোমালোকে মুমিন হোৱা। (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- মানুহক পথনিৰ্দেশনা অহাৰ পিছত তেওঁলোকৰ ঈমান আনাত কি বাধা হ'ল? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- তেওঁলোকে আল্লাহৰ সমকক্ষ স্থাপন কৰিলে, যাতে তেওঁলোকে তেওঁৰ পথৰ পৰা বিপথে নি। কোৱা: তোমালোকে উপভোগ কৰা। (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- তেওঁলোকে আচৰিত হ'ল যে তেওঁলোকৰ মাজৰ পৰাই এজন সতৰ্ককৰ্তা আহিল, আৰু কাফিৰসকলে ক'লে: এওঁ। (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- নিশ্চয় তোমাৰ প্ৰতিপালকেই ভালকৈ জানে কোনে তেওঁৰ পথৰ পৰা পথভ্ৰষ্ট হৈছে। (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- যি মানুহক দেখুৱাবৰ বাবে নিজৰ সম্পদ ব্যয় কৰে আৰু আল্লাহক বিশ্বাস নকৰে। (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- আমি তোমালোকক প্ৰদান কৰা বস্তুৰ পৰা সেই দিন অহাৰ আগতে ব্যয় কৰা। (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- তেওঁ আকাশমণ্ডলত আৰু পৃথিৱীত যি আছে, সকলো তোমালোকৰ অধীনস্থ কৰি দিছে। (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- নিশ্চয় আমি তোমালোকে যি ফালে আমাক মাতা, সেই বিষয়ে সন্দেহত আছো। (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- নিশ্চয় তোমাৰ প্ৰতিপালকে যাক ইচ্ছা কৰে, তাৰ বাবে ৰিজিক বহলাই দিয়ে, আৰু সংকুচিত কৰে; নিশ্চয় তেওঁ। (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- আকাশমণ্ডল আৰু পৃথিৱী আৰু সেই দুয়োৰ মাজত যি আছে, তাৰ প্ৰতিপালক, যদি তোমালোকে দৃঢ়বিশ্বাসী হোৱা। (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- আমি আল্লাহত আৰু আমালৈ অৱতীৰ্ণ কৰা আৰু (উপনবীসকললৈ) অৱতীৰ্ণ কৰা বিষয়বস্তুত ঈমান পাইছো। (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- আৰু যিসকলে অন্যায় কৰিছিল, তেওঁলোকক শংকাকাৰী ধ্বনিয়ে গ্ৰাস কৰিলে; ফলত তেওঁলোকে নিজৰ ঘৰত উপুৰ হৈ পৰিল। (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- সেয়ে, তেওঁলোকে নিজৰ বিষয়ে যি কৰে, তাৰ বাবে তোমালোকৰ ওপৰত কোনো দোষ নাই। (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- তোমাৰ প্ৰতিপালকেই ভালকৈ জানে কোনে তেওঁৰ পথৰ পৰা পথভ্ৰষ্ট হৈছে, আৰু তেওঁ। (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- তেওঁৰ আদেশৰ পৰা ৰূহ (অহী) তেওঁৰ বান্দাসকলৰ মাজৰ যাক ইচ্ছা কৰে, তাৰ ওপৰত প্ৰেৰণ কৰে। (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- আৰু আমি মৰিয়মৰ পুত্ৰ ঈছাক সুস্পষ্ট নিদৰ্শন দান কৰিছিলো আৰু পবিত্ৰ ৰূহৰ দ্বাৰা তেওঁক সমৰ্থন দিছিলো। (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- কিয়ামতৰ দিনা তেওঁলোকৰ মাজত যি বিষয়ত তেওঁলোকে মতভেদ কৰিছিল, তাৰ ফয়ছালা কৰিব। (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- আমি তাৰ ওপৰিভাগ তলিভাগ কৰি দিলোঁ, আৰু তাৰ ওপৰত পোৰা মাটিৰ শিল বৰ্ষণ কৰিলোঁ। (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- তুমি সিহঁতক সতৰ্ক কৰা বা নকৰা, সিহঁতৰ বাবে সমান; সিহঁতে ঈমান নানিব। (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- মানুহৰ পৰা (বিচ্ছিন্ন হৈ), যদি তোমালোকে সত্যবাদী হোৱা, তেন্তে মৃত্যুৰ কামনা কৰা। (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- আল্লাহৰ, তোমালোকৰ তেওঁৰ বাহিৰে কোনো ইলাহ নাই। তেন্তে তোমালোকে তাক্বৱা নকৰা নে? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- আমি তেওঁলোকক যি প্ৰতিশ্ৰুতি দিছো, তাৰ কিছু তোমাক দেখুৱালেও বা তোমাক মৃত্যু দিলেও, অৱশেষত আমালৈকে উভতি আহিব। (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- তেওঁলোকে ক'লে: আমি মৃত্যুবৰণ কৰি মাটি আৰু হাড় হৈ গ'লেও, নিশ্চয় আমি পুনৰুত্থিত হ'ম নে? (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- অনুগ্ৰহ আল্লাহৰ হাতত, তেওঁ যাক ইচ্ছা কৰে, তাক দিয়ে; আল্লাহ। (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- গায়েব আৰু প্ৰত্যক্ষ উভয়কে জনা জনৰ ফালে উভতি যাবা, তেতিয়া তেওঁ তোমালোকক তোমালোকে কৰা কাৰ্যৰ বিষয়ে অৱগত কৰিব। (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- হে ঈমানদাৰসকল, তোমালোকে আল্লাহৰ সেই অনুগ্ৰহৰ কথা স্মৰণ কৰা, যেতিয়া। (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- আমি তোমাৰ পূৰ্বেও কেৱল পুৰুষকেই ৰাছুল হিচাপে প্ৰেৰণ কৰিছিলো, যিসকলৰ প্ৰতি আমি অহী প্ৰেৰণ কৰিছিলো। (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- তেওঁ তাৰ পাপসমূহ মোচন কৰিব আৰু তাক জান্নাতত প্ৰৱেশ কৰাব, যাৰ তলত নৈবাহিনী প্ৰবাহিত। (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- অসুস্থ অৱস্থাত বা ভ্ৰমণত থকা অৱস্থাত, তেন্তে আন দিনৰ পৰা গণনা পূৰণ কৰিব। (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- তেওঁলোকে কেৱল অনুমানৰ অনুসৰণ কৰে, আৰু তেওঁলোক কেৱল অনুমাননিৰ্ভৰহে। (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- যি আল্লাহ আৰু অন্তিম দিনৰ আশা ৰাখে, তাৰ বাবে উত্তম আদৰ্শ। (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- আমি আকাশমণ্ডল আৰু পৃথিৱী আৰু সেই দুয়োৰ মাজত যি আছে, সেইবোৰ সত্যৰ বাহিৰে সৃষ্টি কৰা নাই। (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- তোমাৰ হাত তোমাৰ কোলাত সুমুওৱা, সি কোনো দোষ নোহোৱাকৈ উজ্জ্বল হৈ ওলাব। (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- তেওঁ নিজৰ দয়াৰ দ্বাৰা যাক ইচ্ছা কৰে, তাক নিৰ্বাচিত কৰে; আৰু আল্লাহ মহান অনুগ্ৰহশীল। (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- তুমি জানা নে যে আল্লাহৰ বাবে আকাশমণ্ডল আৰু পৃথিৱীৰ ৰাজ্য? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- তোমালোকে নিজৰ বাবে যি ভাল কাম আগবঢ়াইছা, সেইটো আল্লাহৰ ওচৰত পাবা। (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- আৰু তুমি যি ঠাইৰ পৰা ওলাইছা, সেই ঠাইৰ পৰা তোমাৰ মুখ মছজিদুল হাৰামৰ ফালে ঘূৰাই দিয়া। (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- তেওঁলোকৰ আগত যি পাৰ হৈ গৈছে, আৰু তুমি আল্লাহৰ নিয়মত কেতিয়াও পৰিৱৰ্তন নাপাবা। (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- যাৰ বাবে আকাশমণ্ডল আৰু পৃথিৱীৰ যি আছে, সেইবোৰ। (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- কোনো স্ত্ৰীয়ে গৰ্ভ নধৰে আৰু প্ৰসৱ নকৰে, কিন্তু তেওঁৰ জ্ঞানৰ দ্বাৰাহে। (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- ৰাতি, আৰু তেওঁ সূৰ্য্য আৰু চন্দ্ৰক অধীনস্থ কৰি দিছে; প্ৰত্যেকেই নিৰ্দিষ্ট সময়লৈকে চলি আছে। (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- যাৰ তলত নৈবাহিনী প্ৰবাহিত, তাত তেওঁলোক চিৰস্থায়ী হৈ থাকিব, আৰু সেইটোৱেই হৈছে পুৰস্কাৰ। (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- তেওঁ ক'লে: বৰং তোমালোকৰ মনেই তোমালোকৰ বাবে এটা কাম সুশোভিত কৰিলে; গতিকে ধৈৰ্যই উত্তম। (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- আকাশমণ্ডলত আৰু পৃথিৱীত যি আছে, আৰু নিশ্চয় আল্লাহ। (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- তেওঁলোকৰ ওচৰত কোনো ৰাছুল আহিলে তেওঁলোকে তেওঁক উপহাস কৰিছিল। (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- তেওঁলোকে ক'লে: হে মূছা, হয় তুমি (দণ্ড) দলিয়া দিয়া, নহয় আমি দলিয়াওঁ। (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- তেওঁয়ে তোমালোকক মৃত্যু দিয়েই, আৰু তোমালোকৰ মাজৰ কোনোবা জৰাজীৰ্ণ অৱস্থালৈ উভতাই দিয়া হয়, যাতে। (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- তেওঁলোকৰ প্ৰতিপালকৰ ওচৰত জান্নাত আছে যাৰ তলত নৈবাহিনী প্ৰবাহিত, তাত তেওঁলোক চিৰস্থায়ী হৈ থাকিব। (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- আমি তেওঁলোকৰ অন্তৰত আৱৰণি দিছো যাতে তেওঁলোকে (কোৰআন) নুবুজে, আৰু তেওঁলোকৰ কাণত বধিৰতা। (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- নিশ্চয় আল্লাহৰ প্ৰতিশ্ৰুতি সত্য, কিন্তু তেওঁলোকৰ অধিকাংশই নাজানে। (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- এইটো কাৰণে যে তেওঁলোকে আল্লাহ আৰু তেওঁৰ ৰাছুলৰ বিৰোধিতা কৰিছিল; আৰু যিয়ে আল্লাহৰ বিৰোধিতা কৰে। (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- আৰু যি দিনা তেওঁ তেওঁলোকক মাতিব, তেতিয়া ক'ব: মোৰ অংশীদাৰসকল যিসকলৰ বিষয়ে তোমালোকে ধাৰণা কৰিছিলা, তেওঁলোক ক'ত? (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- তেওঁলোকে দেখা নাইনে যে আল্লাহেই আকাশমণ্ডল আৰু পৃথিৱী সৃষ্টি কৰিছে? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- যিয়ে তোমাক মাটিৰ পৰা, তাৰ পিছত শুক্ৰাণুৰ পৰা, তাৰ পিছত। (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- তেওঁলোকে ক'লেহেঁতেন: হে আমাৰ প্ৰতিপালক, তুমি আমাৰ ওচৰলৈ ৰাছুল কিয় পঠিওৱা নাছিলা, আমি তোমাৰ নিদৰ্শনসমূহ অনুসৰণ কৰিলোহেঁতেন? (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- তাৰ পিছত তেওঁলোকৰ প্ৰতিপালকৰ ফালে তেওঁলোকৰ উভতি যোৱা, তেতিয়া তেওঁ তেওঁলোকে কৰা কাৰ্যৰ বিষয়ে অৱগত কৰিব। (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- তেওঁলোকৰ সেই বিষয়ে কোনো জ্ঞান নাই, তেওঁলোক কেৱল অনুমানকেহে অনুসৰণ কৰে। (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- নিশ্চয় আমি আমাৰ পিতৃ-পুৰুষসকলক এটা মতাদৰ্শৰ ওপৰত পাইছো, আৰু আমি তেওঁলোকৰ পদাংক অনুসৰণকাৰী। (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- যিসকলক কিতাব দিয়া হৈছিল, তেওঁলোকে কেৱল তেওঁলোকৰ ওচৰত জ্ঞান অহাৰ পিছতহে (মতভেদ কৰিছে)। (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- ইব্ৰাহীমে যেতিয়া ক'লে: হে মোৰ প্ৰতিপালক, এই ঠাইক শান্তিৰ ঠাই বনাই দিয়া। (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- তেওঁ তোমালোকৰ বাবে শ্ৰৱণশক্তি, দৃষ্টিশক্তি আৰু হৃদয় সৃষ্টি কৰিছে; তোমালোকে অলপহে কৃতজ্ঞতা প্ৰকাশ কৰা। (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- যিসকলে কোনো প্ৰমাণ নোহোৱাকৈ আল্লাহৰ আয়াতসমূহৰ বিষয়ে বিতণ্ডা কৰে। (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- গতিকে তোমালোকে ইব্ৰাহীমৰ একনিষ্ঠ ধৰ্ম অনুসৰণ কৰা, আৰু তেওঁ মুশৰিকসকলৰ অন্তৰ্ভুক্ত নাছিল। (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- আৰু যেতিয়া আমি তোমালোকক ফিৰআউনৰ পৰিয়ালৰ পৰা উদ্ধাৰ কৰিছিলো, যিসকলে তোমালোকক নিকৃষ্টতম শাস্তি দিছিল। (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- সেইটো হৈছে সঠিক ধৰ্ম, কিন্তু অধিকাংশ মানুহেই নাজানে। (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- তুমি দেখা নাইনে যে আল্লাহে তোমালোকৰ বাবে আকাশমণ্ডলত যি আছে, সেইবোৰ অধীনস্থ কৰি দিছে? (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- যিসকলে অস্বীকাৰ কৰিলে, তেওঁলোকে ক'লে: এইটো স্পষ্ট জাদুৰ বাহিৰে আন একো নহয়। (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- যেতিয়া তেওঁলোকৰ ওচৰত আমাৰ স্পষ্ট আয়াতসমূহ পঠিত হয়, তেতিয়া কাফিৰসকলে কয়। (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- চিৰস্থায়ী জান্নাত, যাৰ তলত নৈবাহিনী প্ৰবাহিত, তাত তেওঁলোক চিৰস্থায়ী হৈ থাকিব। (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- যাক ইচ্ছা, নিশ্চয় আল্লাহ সকলো বস্তুৰ ওপৰত ক্ষমতাবান। (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- যাতে তেওঁ তোমালোকৰ পাপসমূহ মোচন কৰে আৰু তোমালোকক নিৰ্দিষ্ট সময়লৈকে পলম কৰে। (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- তোমালোকে আমাক আমাৰ পিতৃ-পুৰুষসকলে যি ইবাদত কৰিছিল, তাৰ পৰা বাধা দিব খোজা নে? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- যেতিয়া তোমাৰ প্ৰতিপালকে ফেৰেস্তাসকলক ক'লে: নিশ্চয় মই মাটিৰ পৰা মানুহ সৃষ্টি কৰিম। (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- আৰু তেওঁয়েই বতাহ প্ৰেৰণ কৰে, যাৰ দ্বাৰা তেওঁৰ দয়াৰ আগত সুসংবাদ প্ৰেৰণ কৰে। (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- কোৱা: পৃথিৱীত ভ্ৰমণ কৰা আৰু চোৱা যে পৰিণতি কেনেকুৱা হৈছিল। (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- আকাশমণ্ডল আৰু পৃথিৱী সৃষ্টি আৰু ৰাতি আৰু দিনৰ পৰিৱৰ্তনত (নিদৰ্শন আছে)। (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- কোন সেইজন যিয়ে আল্লাহক উত্তম ঋণ দিব, যাৰ বিনিময়ত তেওঁ তাক বহুগুণে বাঢ়াই দিব? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- গতিকে আল্লাহই অৱতীৰ্ণ কৰা অনুসাৰে তেওঁলোকৰ মাজত বিচাৰ কৰা, আৰু তেওঁলোকৰ প্ৰবৃত্তি অনুসৰণ নকৰিবা। (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- তেওঁলোকে কেৱল ফেৰেস্তাসকল তেওঁলোকৰ ওচৰলৈ অহা বা তোমাৰ প্ৰতিপালকৰ আদেশ অহাৰ অপেক্ষা কৰে নেকি? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- যিসকলে আল্লাহৰ ওপৰত মিছা অপবাদ দিছে, তেওঁলোকে সফল নহ'ব। (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- ফিৰআউনৰ পৰিয়াল আৰু তেওঁলোকৰ আগৰ লোকসকলৰ দৰে, তেওঁলোকে আমাৰ আয়াতসমূহক মিছা বুলি কোৱাৰ বাবে। (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- আৰু মুমিনসকলক সুসংবাদ দিয়া যিসকলে সৎকৰ্ম কৰে, যে তেওঁলোকৰ বাবে উত্তম পুৰস্কাৰ আছে। (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- আল্লাহে যাক ইচ্ছা কৰে, তেওঁৰ বান্দাসকলৰ মাজৰ যাৰ বাবে ৰিজিক বহলাই দিয়ে আৰু সংকুচিত কৰে। (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- আৰু তোমালোকক গায়েব আৰু প্ৰত্যক্ষৰ জ্ঞানীৰ ফালে উভতাই অনা হ'ব, তেতিয়া তোমালোকক তোমালোকে কৰা কাৰ্যৰ বিষয়ে অৱগত কৰা হ'ব। (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- আৰু আত্মীয়-সম্পৰ্কীয়সকল, তেওঁলোকৰ কিছুমান আল্লাহৰ কিতাবত আনতকৈ অধিক ঘনিষ্ঠ। (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
""";
